from pathlib import Path
import json,hashlib,subprocess,shutil
s=Path('/workspace/scratch/each-node');repo=Path('/workspace/adamic');gate=json.loads((s/'reconciled.json').read_text());assert gate['passed'] and gate['totals']['exposed']==0
initial='e24f2600a5d8a8521c5128827cad395d47c81c81';latest=subprocess.check_output(['git','rev-parse','origin/main'],cwd=repo,text=True).strip();changed=subprocess.check_output(['git','diff','--name-only',initial,latest],cwd=repo,text=True).splitlines();stageChanges=subprocess.check_output(['git','diff','--name-only',initial,latest,'--','stage3'],cwd=repo,text=True).splitlines();assert not stageChanges,('STOP: oracle inputs changed on main',stageChanges);(s/'main-advance-audit.json').write_text(json.dumps({'initialBase':initial,'finalBase':latest,'changedPaths':changed,'stage3Changes':stageChanges,'nodeOracleInputsUnchanged':True},indent=2)+'\n')
p=subprocess.run(['git','merge','--ff-only','origin/main'],cwd=repo);print('base fast-forward child exit',p.returncode,flush=True);assert p.returncode==0
base=subprocess.check_output(['git','rev-parse','HEAD'],cwd=repo,text=True).strip();(s/'base.json').write_text(json.dumps({'base':base,'initialScoutBase':'e24f2600a5d8a8521c5128827cad395d47c81c81','typescript':'050880ce59e30b356b686bd3144efe24f875ebc8'},indent=2)+'\n')
unit=repo/'stage3/adapt/99-correctness-core-each-node';assert not unit.exists();shutil.copytree(s/'draft',unit);pins=json.loads((unit/'pins.json').read_text());pins['base']=base;(unit/'pins.json').write_text(json.dumps(pins,indent=2)+'\n')
witness=(s/'witness.cjs').read_text().replace("require('/workspace/adamic/stage3/api/node_modules/typescript')","require('typescript')").replace("require('/workspace/adamic/stage3/adapt/99-correctness-core-debug-messages/witness.cjs')","require('../99-correctness-core-debug-messages/witness.cjs')");(unit/'witness.cjs').write_text(witness)
road=repo/'stage3/adapt/99-correctness-core-debug-messages';rp=json.loads((road/'pins.json').read_text());pin=rp['pins'][0];assert pin['owner']=='assertEachNode' and pin['after']==pins['before'];pin['finished']=pins['after'];pin['finishedSha256']=pins['afterSha256'];(road/'pins.json').write_text(json.dumps(rp,indent=2)+'\n')
p=road/'adapt.cjs';t=p.read_text();old="const state=owner.text===pin.before?'before':owner.text===pin.after?'after':undefined;assert(state,`unreviewed owner: ${pin.owner}`);assert.equal(hash(owner.text),pin[state+'Sha256']);";new="const finished=pin.finished!==undefined&&owner.text===pin.finished;const state=owner.text===pin.before?'before':owner.text===pin.after||finished?'after':undefined;assert(state,`unreviewed owner: ${pin.owner}`);assert.equal(hash(owner.text),pin[(finished?'finished':state)+'Sha256']);";assert t.count(old)==1;p.write_text(t.replace(old,new))
p=road/'README.md';p.write_text(p.read_text()+'''\n## Stacked assertEachNode loop recognition\n\nTask 8n7eet3, site 2, Adamic Nov 10 22:01Z. The later\n99-correctness-core-each-node owns the ruled explicit loop and removal of\nthe unused every import. Road (b) now recognizes that exact whole owner as\na finished after state, pinned separately in pins.json. Its original before\nand after pins and four message edits are unchanged. The other three owners\nmust still be after when the loop is present. Any other owner drift, including\na changed loop, still refuses before writing. The later adapter's guards and\nPROOF.md record the finished-state replay and drift refusal.\n''')
p=road/'SHA256SUMS';lines=[]
for line in p.read_text().splitlines():
 digest,name=line.split('  ',1)
 if name in ['adapt.cjs','pins.json','README.md']:digest=hashlib.sha256((road/name).read_bytes()).hexdigest()
 lines.append(digest+'  '+name)
p.write_text('\n'.join(lines)+'\n');print('installed exact loop adapter and road (b) recognition; base',base)
